50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	};
58	
59	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
60	
61	const quote = ({ items }: QuoteStep): QuoteResult => {
62	  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
63	
64	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE;
65	
66	  return {
67	    premium: Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE),
68	  };
69	};
70	
71	const runStep = (step: Step): StepResult => {
72	  if (step.op === "quote") return quote(step);
73	
74	  throw new Error(`unsupported step: ${step.op}`);
75	};
76	
77	export const runScenario = (scenario: Scenario): ScenarioResult => ({
78	  results: scenario.steps.map(runStep),
79	});
